import{_ as p,r as n,o,c,e as a,a as l,s as r}from"./chunks/framework.CXcwiNg-.js";const f=JSON.parse('{"title":"Сериализация - October CMS - 3.x","titleTemplate":false,"description":"","frontmatter":{},"headers":[{"level":2,"title":"Основы использования","slug":"основы-использования","link":"#основы-использования","children":[{"level":4,"title":"Преобразование модели в массив","slug":"преобразование-модели-в-массив","link":"#преобразование-модели-в-массив","children":[]},{"level":4,"title":"Преобразование модели в JSON","slug":"преобразование-модели-в-json","link":"#преобразование-модели-в-json","children":[]}]},{"level":2,"title":"Скрытие атрибутов из JSON","slug":"скрытие-атрибутов-из-json","link":"#скрытие-атрибутов-из-json","children":[]},{"level":2,"title":"Добавление значений в JSON","slug":"добавление-значении-в-json","link":"#добавление-значении-в-json","children":[]}],"relativePath":"3.x/ru/extend/database/serialization.md","filePath":"3.x/ru/extend/database/serialization.md"}'),i={name:"3.x/ru/extend/database/serialization.md"};function u(k,s,d,g,h,m){const e=n("pre-heading"),t=n("post-heading");return o(),c("div",null,[a(e),s[0]||(s[0]=l("h1",null,"Сериализация",-1)),a(t),s[1]||(s[1]=r(`<p>При создании JSON API вам часто потребуется преобразовывать модели и связи в массивы или JSON. Модели включают удобные методы для выполнения этих преобразований, а также для управления тем, какие атрибуты включаются в сериализацию.</p><h2 id="основы-использования"><a href="#основы-использования" class="header-anchor">#</a> Основы использования</h2><h4 id="преобразование-модели-в-массив"><a href="#преобразование-модели-в-массив" class="header-anchor">#</a> Преобразование модели в массив</h4><p>Для преобразования модели и её загруженных <a href="./relations.html">связей</a> в массив используйте метод <code>toArray</code>. Этот метод является рекурсивным, поэтому все атрибуты и все связи (включая связи связей) будут преобразованы в массивы:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$user</span> <span class="token operator">=</span> <span class="token class-name static-context">User</span><span class="token operator">::</span><span class="token function">with</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;roles&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">first</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token keyword">return</span> <span class="token variable">$user</span><span class="token operator">-&gt;</span><span class="token function">toArray</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Вы также можете преобразовать <a href="./collections.html">коллекции</a> в массивы:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$users</span> <span class="token operator">=</span> <span class="token class-name static-context">User</span><span class="token operator">::</span><span class="token function">all</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token keyword">return</span> <span class="token variable">$users</span><span class="token operator">-&gt;</span><span class="token function">toArray</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="преобразование-модели-в-json"><a href="#преобразование-модели-в-json" class="header-anchor">#</a> Преобразование модели в JSON</h4><p>Для преобразования модели в JSON используйте метод <code>toJson</code>. Как и <code>toArray</code>, метод <code>toJson</code> является рекурсивным, поэтому все атрибуты и связи будут преобразованы в JSON:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$user</span> <span class="token operator">=</span> <span class="token class-name static-context">User</span><span class="token operator">::</span><span class="token function">find</span><span class="token punctuation">(</span><span class="token number">1</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token keyword">return</span> <span class="token variable">$user</span><span class="token operator">-&gt;</span><span class="token function">toJson</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Альтернативно вы можете привести модель или коллекцию к строке, что автоматически вызовет метод <code>toJson</code>:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$user</span> <span class="token operator">=</span> <span class="token class-name static-context">User</span><span class="token operator">::</span><span class="token function">find</span><span class="token punctuation">(</span><span class="token number">1</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token keyword">return</span> <span class="token punctuation">(</span><span class="token keyword type-casting">string</span><span class="token punctuation">)</span> <span class="token variable">$user</span><span class="token punctuation">;</span>
</code></pre></div><p>Поскольку модели и коллекции преобразуются в JSON при приведении к строке, вы можете возвращать объекты Model напрямую из маршрутов, обработчиков AJAX или контроллеров вашего приложения:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Route</span><span class="token operator">::</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;users&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token class-name static-context">User</span><span class="token operator">::</span><span class="token function">all</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h2 id="скрытие-атрибутов-из-json"><a href="#скрытие-атрибутов-из-json" class="header-anchor">#</a> Скрытие атрибутов из JSON</h2><p>Иногда вы можете захотеть ограничить атрибуты, такие как пароли, которые включаются в массив или JSON-представление вашей модели. Для этого добавьте определение свойства <code>$hidden</code> в вашу модель:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">namespace</span> <span class="token package">Acme<span class="token punctuation">\\</span>Blog<span class="token punctuation">\\</span>Models</span><span class="token punctuation">;</span>

<span class="token keyword">use</span> <span class="token package">Model</span><span class="token punctuation">;</span>

<span class="token keyword">class</span> <span class="token class-name-definition class-name">User</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token comment">/**
     * The attributes that should be hidden for arrays.
     *
     * @var array
     */</span>
    <span class="token keyword">protected</span> <span class="token variable">$hidden</span> <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;password&#39;</span><span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>Альтернативно вы можете использовать свойство <code>$visible</code> для определения белого списка атрибутов, которые должны быть включены в массив и JSON-представление вашей модели:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">User</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token comment">/**
     * The attributes that should be visible in arrays.
     *
     * @var array
     */</span>
    <span class="token keyword">protected</span> <span class="token variable">$visible</span> <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;first_name&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;last_name&#39;</span><span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h2 id="добавление-значении-в-json"><a href="#добавление-значении-в-json" class="header-anchor">#</a> Добавление значений в JSON</h2><p>Иногда вам может потребоваться добавить атрибуты массива, которые не имеют соответствующего столбца в базе данных. Для этого сначала определите <a href="./mutators.html">аксессор</a> для значения:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">User</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token comment">/**
     * Get the administrator flag for the user.
     *
     * @return bool
     */</span>
    <span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">getIsAdminAttribute</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
    <span class="token punctuation">{</span>
        <span class="token keyword">return</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token property">attributes</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;admin&#39;</span><span class="token punctuation">]</span> <span class="token operator">==</span> <span class="token string single-quoted-string">&#39;yes&#39;</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre></div><p>После создания аксессора добавьте имя атрибута в свойство <code>appends</code> модели:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">User</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token comment">/**
     * The accessors to append to the model&#39;s array form.
     *
     * @var array
     */</span>
    <span class="token keyword">protected</span> <span class="token variable">$appends</span> <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;is_admin&#39;</span><span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>После добавления атрибута в список <code>appends</code> он будет включён как в массив, так и в JSON-представление модели. Атрибуты в массиве <code>appends</code> также будут учитывать настройки <code>visible</code> и <code>hidden</code>, сконфигурированные в модели.</p>`,25))])}const y=p(i,[["render",u]]);export{f as __pageData,y as default};
